CREATE TABLE GROUPS (
--	ID NUMBER GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) PRIMARY KEY,
	ID NUMBER NOT NULL,
	NAME VARCHAR2(100) NOT NULL,
	C_VAL NUMBER DEFAULT 0,
	CONSTRAINT group_id_pk PRIMARY KEY (ID)
);

CREATE TABLE STUDENTS (
--	ID NUMBER GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) PRIMARY KEY,
	STUDENT_ID NUMBER NOT NULL,
	NAME VARCHAR2(100) NOT NULL,
	GROUP_ID NUMBER NOT NULL,
	CONSTRAINT student_id_pk PRIMARY KEY (STUDENT_ID)
--	CONSTRAINT FK_STUDENT_GROUPS
--		FOREIGN KEY (GROUP_ID)
--		REFERENCES GROUPS(ID)
);

CREATE SEQUENCE student_id_seq START WITH 1 INCREMENT BY 1;
CREATE SEQUENCE group_id_seq START WITH 1 INCREMENT BY 1;

CREATE TABLE STUDENTS_LOG (
	LOG_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	STUDENT_ID NUMBER,
	ACTION_TYPE VARCHAR2(10),
	OLD_NAME VARCHAR(100),
	NEW_NAME VARCHAR(100),
	OLD_GROUP_ID NUMBER,
	NEW_GROUP_ID NUMBER,
	ACTION_TIMESTAMP TIMESTAMP DEFAULT SYSTIMESTAMP
);






